HEAD='<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0E0B1F"><link rel="preload" href="/fonts/Vazirmatn-Light.ttf" as="font" crossorigin><link rel="stylesheet" href="/style.css">'
NAV=f'<header><div class="w"><a class="logo" href="/"><span class="mark">ش</span><span>تجارت الکترونیک شایسته ایرانیان<small>SHAYESTEH IRANIAN</small></span></a><nav><a href="/#about">درباره ما</a><a href="/#products">محصولات</a><a href="/#team">تیم</a><a class="btn" href="/postino/">پستینو</a></nav></div></header>'
FOOT='<footer><div class="w"><span>© تجارت الکترونیک شایسته ایرانیان — قائم‌شهر، مازندران</span><span>تلفن: <span class="ph">[شماره تماس]</span> · ایمیل: <span class="ph">[ایمیل]</span> · تلگرام: <span class="ph">[آیدی تلگرام]</span></span></div></footer>'
JS='<script>const o=new IntersectionObserver(e=>e.forEach(x=>{if(x.isIntersecting){x.target.classList.add("in");o.unobserve(x.target)}}),{threshold:.12});document.querySelectorAll(".rv").forEach((el,i)=>{el.style.transitionDelay=(i%4)*90+"ms";o.observe(el)})</script>'
def page(title,desc,body,extra=''):
    return f'<!doctype html><html lang="fa" dir="rtl"><head>{HEAD}<title>{title}</title><meta name="description" content="{desc}"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:locale" content="fa_IR"><meta property="og:type" content="website"></head><body>{NAV}{body}{FOOT}{JS}{extra}</body></html>'
def mem(u,n,r):return f'<div class="card mem rv"><img src="/img/team/{u}.png" alt="{n}"><h3>{n}</h3><div class="role">{r}</div><a class="gh" href="https://github.com/{u}" target="_blank" rel="noopener">{s("gh")}github.com/{u}</a></div>'
home=f'''<div class="hero"><div class="orb"></div><div class="w rv"><span class="eyebrow">شرکت برنامه‌نویسی</span><h1>نرم‌افزارِ هوشمند<br><b>برای کسب‌وکارهای ایرانی</b></h1>
<p class="lead">تجارت الکترونیک شایسته ایرانیان یک تیم برنامه‌نویسی است که با هوش مصنوعی، اتوماسیون و توسعه‌ی وب، کارهای تکراری کسب‌وکارها را خودکار می‌کند و محصول دیجیتال می‌سازد.</p>
<div class="cta"><a class="btn" href="/postino/">آشنایی با پستینو {s("arr")}</a><a class="btn" href="https://www.nibero.ir" target="_blank" rel="noopener">آشنایی با نیبرو {s("arr")}</a></div></div></div>
<section id="about"><div class="w"><div class="head rv"><span class="eyebrow">تخصص‌ها</span><h2>چه <b>کاری</b> می‌کنیم؟</h2><p class="sub">چهار تخصص در یک تیم.</p></div><div class="g">
<div class="card rv"><div class="ic">{s("ai")}</div><h3>هوش مصنوعی</h3><p>چت‌بات، دستیار هوشمند و مدل‌های زبانی، هم ابری و هم روی سیستم خود شما.</p></div>
<div class="card rv"><div class="ic">{s("bolt")}</div><h3>اتوماسیون</h3><p>ربات تلگرام، تولید خودکار محتوا و خودکارسازی کارهای تکراری.</p></div>
<div class="card rv"><div class="ic">{s("web")}</div><h3>توسعه وب</h3><p>فرانت‌اند و بک‌اند، فروشگاه و پلتفرم‌های تحت وب.</p></div>
<div class="card rv"><div class="ic">{s("srv")}</div><h3>دواپس</h3><p>استقرار، سرور و پایداری سرویس‌ها.</p></div></div></div></section>
<section id="products"><div class="w"><div class="head rv"><span class="eyebrow">محصولات</span><h2>محصولات <b>ما</b></h2><p class="sub">چیزهایی که ساخته‌ایم و در حال ساختنیم.</p></div><div class="g prods">
<div class="card feat rv"><span class="badge">محصول جدید</span><h3><b>پستینو</b> Postino</h3><p>مدیریت هوشمند پیج کسب‌وکار با هوش مصنوعی: پست، ریل، استوری و تقویم محتوایی؛ محتوا را ما می‌سازیم، انتشار با یک کلیک از گوشی خودتان.</p><div class="pr"><strong>۶</strong> میلیون تومان در ماه</div><a class="btn" href="/postino/">مشاهده و سفارش {s("arr")}</a></div>
<div class="card feat rv"><span class="badge">پلتفرم کسب‌وکار</span><h3><b>نیبرو</b> Nibero</h3><p>شبکه‌ی تجاری و پلتفرم کسب‌وکار دیجیتال: بازار آنلاین محصولات (از جمله قطعات موبایل) با فروشگاه آنلاین، حسابداری رایگان و سیستم ERP برای فروشنده‌ها.</p><div class="pr"><strong>nibero.ir</strong> فروشگاه آنلاین · حسابداری · ERP</div><a class="btn" href="https://www.nibero.ir" target="_blank" rel="noopener">ورود به نیبرو {s("arr")}</a></div>
</div></div></section>
<section id="team"><div class="w"><div class="head rv"><span class="eyebrow">تیم</span><h2>تیم <b>ما</b></h2><p class="sub">پنج نفر، یک هدف.</p></div>
<div class="card lead-m rv"><img src="/img/team/MiladLotfi66.png" alt="میلاد لطفی"><div><span class="badge" style="margin-bottom:12px;display:inline-block">مدیرعامل</span><h3><b>میلاد لطفی</b></h3><div class="role">مدیرعامل و برنامه‌نویس فول‌استک</div><a class="gh" href="https://github.com/MiladLotfi66" target="_blank" rel="noopener">{s("gh")}github.com/MiladLotfi66</a></div></div>
<div class="g team">{mem("SamanQasempour","سامان","دواپس")}{mem("MaryamTalebi88","مریم","فرانت‌اند و بک‌اند")}{mem("hasti-espahlar86","هستی","هوش مصنوعی")}{mem("yasinfallahati","یاسین","اتوماسیون")}</div></div></section>'''
feats=[("۱۲ پست یا ریل در ماه","هفته‌ای ۳ محتوای اختصاصی برند شما"),("۲ استوری در روز","حضور همیشگی جلوی چشم مشتری‌ها"),("۸ ادیت ویدیوی حرفه‌ای در ماه","تدوین ریتم‌دار، زیرنویس و کاور"),("تقویم محتوایی و ایده‌پردازی روزانه","بر اساس ترندها و مناسبت‌ها"),("پاسخ آماده برای سؤال‌های پرتکرار دایرکت","جواب سریع و یکدست"),("گزارش ماهانه‌ی رشد پیج","می‌بینید پیج کجا بوده و کجا رفته"),("تکمیل پیج در شروع کار","بیو، هایلایت و کاورهای هماهنگ")]
li=''.join(f'<li>{s("chk")}<span><b>{a}</b>{b}</span></li>' for a,b in feats)
post=f'''<div class="hero"><div class="orb"></div><div class="w rv"><span class="eyebrow">محصول جدید شایسته ایرانیان</span><h1>پستینو<br><b>پیج‌تان را به هوش مصنوعی بسپارید</b></h1>
<p class="lead">شما کسب‌وکارتان را بچرخانید؛ ایده، ساخت و آماده‌سازی محتوای پیج با ما.</p><div class="cta"><a class="btn" href="#order">ثبت درخواست {s("arr")}</a><a class="btn o" href="#plan">مشاهده‌ی پلن</a></div></div></div>
<section id="plan"><div class="w"><div class="head rv"><span class="eyebrow">پلن</span><h2>یک پلن، <b>همه‌چیز</b></h2></div><div class="two">
<div class="card price rv"><span class="eyebrow">یک پلن کامل</span><div class="num">۶</div><div class="u">میلیون تومان</div><div class="per">در ماه</div><ul><li>همه‌چیز در یک بسته</li><li>بدون هزینه‌ی پنهان</li></ul><a class="btn" href="#order">ثبت درخواست {s("arr")}</a></div>
<div class="card rv"><h3>در این پلن چه می‌گیرید؟</h3><ul class="list">{li}</ul></div></div></div></section>
<section><div class="w"><div class="head rv"><span class="eyebrow">روند</span><h2>همکاری در <b>۴ قدم</b></h2></div><div class="g steps">
<div class="card rv"><h3>جلسه‌ی آشنایی</h3><p>شناخت برند، مخاطب و هدف‌ها</p></div><div class="card rv"><h3>ساخت محتوا</h3><p>ایده، طراحی، ویدیو و کپشن</p></div><div class="card rv"><h3>تأیید شما</h3><p>هیچ چیز بی‌اجازه‌ی شما منتشر نمی‌شود</p></div><div class="card rv"><h3>انتشار</h3><p>با یک کلیک از گوشی خودتان</p></div></div></div></section>
<section><div class="w g">
<div class="card rv"><div class="ic">{s("lock")}</div><h3>امنیت پیج شما اولویت ماست</h3><p>ما <b style="color:var(--c);font-weight:500">رمز پیج شما را نمی‌خواهیم.</b> محتوای آماده و تأییدشده را تحویل می‌گیرید و خودتان با یک کلیک منتشر می‌کنید؛ پیج همیشه کاملاً در اختیار خودتان می‌ماند.</p></div>
<div class="card rv"><div class="ic">{s("play")}</div><h3>نمونه‌کار: پیج «نبض فردا»</h3><p>پیجی که محتوایش با همین سیستم هوشمند ساخته می‌شود؛ یکی از ریل‌های اخیرش حدود ۱٬۲۰۰ بازدید گرفت.</p><p style="margin-top:10px"><a href="https://www.instagram.com/nabz_farda/" dir="ltr">@nabz_farda</a> · <a href="https://nabz-farda.vercel.app">nabz-farda.vercel.app</a></p></div></div></section>
<section id="order"><div class="w"><div class="card rv" style="max-width:720px;margin:auto;padding:44px 32px"><span class="eyebrow">سفارش</span><h2>ثبت <b>درخواست</b></h2><p class="sub" style="margin-bottom:28px">فرم را پر کنید؛ کارشناسان ما با شما تماس می‌گیرند. پرداخت پس از هماهنگی با کارشناس انجام می‌شود.</p>
<form id="f"><div class="fr"><input name="name" placeholder="نام و نام خانوادگی" required><input name="biz" placeholder="نام کسب‌وکار" required></div><div class="fr"><input name="page" placeholder="آیدی پیج (مثلاً @mybrand)" required><input name="phone" type="tel" inputmode="tel" placeholder="شماره موبایل (۰۹...)" required></div><select name="time"><option value="">بهترین زمان تماس</option><option>صبح</option><option>ظهر</option><option>عصر</option></select><input name="website" tabindex="-1" autocomplete="off" style="position:absolute;left:-9999px" aria-hidden="true"><textarea name="note" rows="3" placeholder="توضیحات (اختیاری)"></textarea><button class="btn" style="justify-self:start">ارسال درخواست {s("arr")}</button><p id="msg" style="margin:0"></p></form>
<p class="sub" style="margin-top:18px;font-size:.88rem">یا در تلگرام پیام دهید: <span class="ph">[آیدی تلگرام]</span></p></div></div></section>'''
ojs='<script>const f=document.getElementById("f"),m=document.getElementById("msg");f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector("button");b.disabled=true;m.textContent="در حال ارسال...";try{const r=await fetch("/api/postino-lead",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(Object.fromEntries(new FormData(f)))});const j=await r.json().catch(()=>({}));if(r.ok&&j.ok){f.reset();m.style.color="#D9B26F";m.textContent="درخواست شما ثبت شد. کارشناسان ما به‌زودی با شما تماس می‌گیرند."}else{m.style.color="#e88";m.textContent=j.error||"ارسال ناموفق بود؛ دوباره تلاش کنید."}}catch(_){m.style.color="#e88";m.textContent="خطا در اتصال؛ دوباره تلاش کنید."}b.disabled=false}</script>'
open('index.html','w').write(page('تجارت الکترونیک شایسته ایرانیان | هوش مصنوعی، اتوماسیون و توسعه وب','شرکت برنامه‌نویسی تجارت الکترونیک شایسته ایرانیان؛ تیم هوش مصنوعی، اتوماسیون، توسعه وب و دواپس. سازنده‌ی پستینو و نیبرو.',home))
open('postino/index.html','w').write(page('پستینو | مدیریت هوشمند پیج کسب‌وکار با هوش مصنوعی','پستینو: ۱۲ پست و ریل، ۲ استوری در روز، ۸ ادیت ویدیو و گزارش ماهانه؛ ماهی ۶ میلیون تومان. بدون نیاز به رمز پیج.',post,ojs))
